div.script:
// Type filtering functionality
function filterByType(typeName) {
const cards = document.querySelectorAll('.card-container');
const noCoursesMessage = document.getElementById('noCoursesMessage');
const filterResults = document.getElementById('filterResults');
const filterResultsText = document.getElementById('filterResultsText');
let visibleCount = 0;

cards.forEach(card => {
const cardType = card.getAttribute('data-type');
if (!typeName || cardType === typeName) {
card.classList.remove('hidden');
visibleCount++;
} else {
card.classList.add('hidden');
}
});

// Update results info
if (typeName) {
filterResults.classList.remove('d-none');
filterResultsText.textContent = `Showing ${visibleCount} Training of type "${typeName}"`;
} else {
filterResults.classList.add('d-none');
filterResultsText.textContent = 'Showing all training';
}

// Show/hide no courses message
if (visibleCount === 0) {
noCoursesMessage.classList.remove('d-none');
} else {
noCoursesMessage.classList.add('d-none');
}
}

// Initialize filter functionality
document.addEventListener('DOMContentLoaded', function() {
const typeFilter = document.getElementById('typeFilter');
if (typeFilter) {
typeFilter.addEventListener('change', function() {
filterByType(this.value);
});
}
});

function showCustomAlert() {
document.getElementById('customAlert').classList.remove('d-none');
document.getElementById('customAlert').classList.add('d-block');
}

function showStudentId() {
document.getElementById('screenTwo').classList.remove('d-none');
document.getElementById('screenTwo').classList.add('d-block');
document.getElementById('screenOne').classList.remove('d-block');
document.getElementById('screenOne').classList.add('d-none');
}

function hideStudentId() {
document.getElementById('screenOne').classList.remove('d-none');
document.getElementById('screenOne').classList.add('d-block');
document.getElementById('screenTwo').classList.remove('d-block');
document.getElementById('screenTwo').classList.add('d-none');
}

function closeAlert() {
document.getElementById('customAlert').classList.add('d-none');
document.getElementById('customAlert').classList.remove('d-block');
}

function closeModal() {
document.getElementById('levelModal').classList.remove('show');
}

// Close modal when clicking outside
document.addEventListener('click', function(event) {
const modal = document.getElementById('levelModal');
if (event.target === modal) {
closeModal();
}
});

// Category filter functionality
let filterTabs = document.querySelectorAll('.filter-tab');
filterTabs.forEach(tab => {
tab.addEventListener('click', () => {
filterTabs.forEach(t => t.classList.remove('active'));
tab.classList.add('active');
});
});

let onecategory = document.querySelector('button[data-filter="category"]');
if (onecategory) {
onecategory.addEventListener('click', () => {
document.querySelector("#categoryDropdown").classList.remove('d-none');
});
}

let allcategory = document.querySelector('button[data-filter="all"]');
if (allcategory) {
allcategory.addEventListener('click', () => {
document.querySelector("#categoryDropdown").classList.add('d-none');
// Reset filter to show all courses
filterByType('');
});
}

// Card description hover effects
document.querySelectorAll('.card-description').forEach(p => {
// default: clamp to 2 lines
p.style.display = '-webkit-box';
p.style.webkitBoxOrient = 'vertical';
p.style.webkitLineClamp = '2';
p.style.overflow = 'hidden';
p.style.textOverflow = 'ellipsis';
p.style.transition = 'all 0.2s ease-in-out';

// on hover: show full text
p.addEventListener('mouseenter', () => {
p.style.webkitLineClamp = 'unset';
p.style.overflow = 'visible';
});

// on leave: clamp again
p.addEventListener('mouseleave', () => {
p.style.webkitLineClamp = '2';
p.style.overflow = 'hidden';
});
});

// Enhanced compact tooltip functionality
document.addEventListener('DOMContentLoaded', function() {
// Weekly info icon tooltips
const weeklyIcons = document.querySelectorAll('.weekly-info-icon');
weeklyIcons.forEach(icon => {
icon.addEventListener('mouseenter', function() {
icon.setAttribute('title', 'This course uses weekly scheduling');
});
});

// Compact hover for week details
const weekHoverElements = document.querySelectorAll('.week-details-hover');
weekHoverElements.forEach(element => {
const tooltip = element.querySelector('.week-tooltip');
if (tooltip) {
element.addEventListener('mouseenter', function() {
tooltip.style.opacity = '1';
tooltip.style.visibility = 'visible';
tooltip.style.transform = 'translateY(-110%)';
});

element.addEventListener('mouseleave', function() {
tooltip.style.opacity = '0';
tooltip.style.visibility = 'hidden';
tooltip.style.transform = 'translateY(-100%)';
});
}
});

// Enhanced remaining count display
const remainingCounts = document.querySelectorAll('.remaining-count');
remainingCounts.forEach(count => {
const value = parseInt(count.textContent);
if (value === 0) {
count.classList.add('full');
} else if (value <= 5) {
count.classList.add('limited');
} else {
count.classList.add('available');
}
});
});
